        align-items: center;
        gap: 0.7rem;
        font-weight: 900;
        letter-spacing: 0.02em;
      }

      .brand-mark {
        width: 2.1rem;
        height: 2.1rem;
        border-radius: 0.8rem;
        background:
          linear-gradient(135deg, rgba(125, 211, 252, 0.95), rgba(225, 29, 72, 0.85));
