        width: 100%;
        overflow: hidden;
        border: 1px solid rgba(185, 195, 211, 0.16);
        border-radius: var(--radius);
        background: rgba(17, 24, 39, 0.82);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
      }

      .image-column {
        display: flex;
        flex-direction: column;
        gap: 1rem;
        padding: clamp(0.75rem, 2vw, 1.1rem);
