        letter-spacing: -0.07em;
      }

      .description {
        max-width: 36rem;
        margin-bottom: 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.7;
      }

      .metadata {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0.75rem;
      }

      .metadata div {
        border: 1px solid rgba(185, 195, 211, 0.14);
        border-radius: 18px;
        padding: 0.85rem;
        background: rgba(255, 255, 255, 0.035);
      }

      .metadata dt {
        color: var(--muted);
        font-size: 0.76rem;
        font-weight: 800;
        text-transform: uppercase;
      }

      .metadata dd {
        margin: 0.25rem 0 0;
        font-weight: 900;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
      }

      .button-secondary {
        border: 1px solid rgba(185, 195, 211, 0.28);
        background: rgba(255, 255, 255, 0.06);
        color: var(--text);
      }

      .trigger,
      .button-danger {
        background: linear-gradient(135deg, var(--danger), var(--danger-strong));
        color: #fff;
        box-shadow: 0 14px 32px rgba(225, 29, 72, 0.28);
      }

      .trigger:hover,
      .button-danger:hover {
        filter: brightness(1.08);
      }

      .button-secondary:hover {
        background: rgba(255, 255, 255, 0.11);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--accent);
        font-weight: 800;
      }

      dialog {
        width: min(92vw, 30rem);
        max-height: min(90vh, 42rem);
        overflow: auto;
        border: 1px solid rgba(251, 113, 133, 0.36);
        border-radius: 26px;
        padding: 0;
        color: var(--text);
        background: linear-gradient(180deg, #182235, #101827);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(2, 6, 23, 0.74);
        backdrop-filter: blur(7px);
      }

      .dialog-panel {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3.25rem;
        height: 3.25rem;
        margin-bottom: 1rem;
        place-items: center;
        border: 1px solid rgba(251, 113, 133, 0.35);
        border-radius: 1.15rem;
        background: rgba(251, 113, 133, 0.12);
        color: #fecdd3;
        font-size: 1.45rem;
      }

      .dialog-title {
        margin-bottom: 0.65rem;
        font-size: clamp(1.6rem, 6vw, 2.15rem);
        line-height: 1.05;
        letter-spacing: -0.045em;
      }

      .dialog-copy {
        color: var(--muted);
        line-height: 1.65;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      @media (max-width: 760px) {
        .preview-card {
          grid-template-columns: 1fr;
        }

        .details-panel {
          padding: 0 clamp(1.25rem, 4vw, 2rem) clamp(1.25rem, 4vw, 2rem);
        }

        .image-frame,
        .image-frame img {
          min-height: 18rem;
        }

        .topbar {
          align-items: flex-start;
          flex-direction: column;
