          background: ButtonFace;
          color: ButtonText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="root"></div>

    <script>
      const image = {
        title: "Midnight Library",
        description:
          "A moody architectural study with blue neon light across a quiet reading room.",
        source:
          "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 900'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='%23070a15'/%3E%3Cstop offset='.55' stop-color='%23142a45'/%3E%3Cstop offset='1' stop-color='%237f1d1d'/%3E%3C/linearGradient%3E%3CradialGradient id='r' cx='.28' cy='.25' r='.68'%3E%3Cstop stop-color='%237dd3fc' stop-opacity='.7'/%3E%3Cstop offset='.5' stop-color='%2338bdf8' stop-opacity='.16'/%3E%3Cstop offset='1' stop-color='%23000000' stop-opacity='0'/%3E%3C/radialGradient%3E%3C/defs%3E%3Crect width='1200' height='900' fill='url(%23g)'/%3E%3Crect width='1200' height='900' fill='url(%23r)'/%3E%3Cg fill='none' stroke='%23dbeafe' stroke-opacity='.35' stroke-width='7'%3E%3Cpath d='M160 720h880M210 210v510M390 260v460M570 190v530M750 250v470M930 180v540'/%3E%3Cpath d='M190 620h780M210 500h720M230 380h700M250 270h720'/%3E%3C/g%3E%3Cg fill='%23f8fafc' fill-opacity='.82'%3E%3Ccircle cx='780' cy='160' r='38'/%3E%3Crect x='170' y='690' width='760' height='22' rx='11'/%3E%3C/g%3E%3Cg fill='%23fb7185' fill-opacity='.5'%3E%3Crect x='248' y='312' width='82' height='18' rx='9'/%3E%3Crect x='610' y='532' width='96' height='18' rx='9'/%3E%3Crect x='790' y='422' width='74' height='18' rx='9'/%3E%3C/g%3E%3C/svg%3E",
        alt: "Blue and rose abstract illustration of a quiet library interior at night.",
        size: "4.8 MB",
        type: "PNG",
      };

      function el(tagName, props = {}, children = []) {
        const node = document.createElement(tagName);

        Object.entries(props).forEach(([key, value]) => {
          if (key === "className") {
            node.className = value;
          } else if (key === "text") {
            node.textContent = value;
          } else if (key.startsWith("on") && typeof value === "function") {
            node.addEventListener(key.slice(2).toLowerCase(), value);
          } else {
            node.setAttribute(key, value);
          }
        });

        children.forEach((child) => {
          node.append(child);
        });

        return node;
      }

      function Header() {
        return el("header", { className: "topbar" }, [
          el("div", { className: "brand", "aria-label": "Nocturne Photos" }, [
            el("span", { className: "brand-mark", "aria-hidden": "true" }),
            el("span", { text: "Nocturne Photos" }),
          ]),
          el("a", { className: "library-link", href: "#", text: "Back to library" }),
        ]);
      }

      function ImagePreview() {
        return el("article", { className: "preview-card", "aria-labelledby": "image-title" }, [
          el("div", { className: "image-column" }, [
            el("div", { className: "image-frame" }, [
              el("img", { src: image.source, alt: image.alt }),
            ]),
            el("div", { className: "actions" }, [
              el("button", {
                type: "button",
                className: "trigger",
                id: "delete-trigger",
                text: "Delete image",
              }),
              el("button", {
                type: "button",
                className: "button-secondary",
                text: "Download",
              }),
            ]),
            el("p", {
              className: "status",
              id: "status-message",
              "aria-live": "polite",
            }),
          ]),
          el("section", { className: "details-panel", "aria-label": "Image details" }, [
            el("p", { className: "eyebrow", text: "Image preview" }),
            el("h1", { id: "image-title", text: image.title }),
            el("p", { className: "description", text: image.description }),
            el("dl", { className: "metadata" }, [
              el("div", {}, [
                el("dt", { text: "File type" }),
                el("dd", { text: image.type }),
              ]),
              el("div", {}, [
                el("dt", { text: "Size" }),
                el("dd", { text: image.size }),
              ]),
            ]),
          ]),
        ]);
      }

      function DeleteDialog() {
        return el("dialog", {
          id: "delete-dialog",
          "aria-labelledby": "dialog-title",
          "aria-describedby": "dialog-description",
        }, [
          el("div", { className: "dialog-panel" }, [
            el("div", { className: "dialog-icon", "aria-hidden": "true", text: "!" }),
            el("h2", {
              className: "dialog-title",
              id: "dialog-title",
              text: "Delete this image?",
            }),
            el("p", {
              className: "dialog-copy",
              id: "dialog-description",
              text:
                "This will remove Midnight Library from your library. This action cannot be undone.",
            }),
            el("div", { className: "dialog-actions" }, [
              el("button", {
                type: "button",
                className: "button-secondary",
                id: "cancel-delete",
                text: "Cancel",
              }),
              el("button", {
                type: "button",
                className: "button-danger",
                id: "confirm-delete",
                text: "Delete image",
              }),
            ]),
          ]),
        ]);
      }

      function App() {
        return el("div", { className: "app-shell" }, [
          Header(),
          el("main", { id: "main" }, [ImagePreview()]),
          DeleteDialog(),
        ]);
      }

      const root = document.getElementById("root");
      root.append(App());

      const dialog = document.getElementById("delete-dialog");
      const trigger = document.getElementById("delete-trigger");
      const cancelButton = document.getElementById("cancel-delete");
      const confirmButton = document.getElementById("confirm-delete");
      const statusMessage = document.getElementById("status-message");

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        dialog.close("delete");
        statusMessage.textContent = "Midnight Library was deleted from your library.";
      });
    </script>
  </body>
</html>
