      }));
    });
    checks.push({ state, violations: result });
    if (state === 'open') await page.keyboard.press('Escape');
  }

  const wcag = checks.map(check => ({
    state: check.state,
    violations: check.violations.filter(v => !v.tags.includes('best-practice'))
  }));
  console.log(JSON.stringify(wcag, null, 2));
  await browser.close();
  process.exit(wcag.some(c => c.violations.length) ? 1 : 0);
})().catch(async (error) => {
  console.error(error.stack || error.message);
  process.exit(2);
});
